:root {
  --bg: #06030c;
  --bg-2: #10051f;
  --ink: #fbf7ff;
  --muted: #b9a9cc;
  --muted-2: #7f6e99;
  --gold: #ffd166;
  --gold-hot: #ffe9a8;
  --gold-deep: #a76a12;
  --magenta: #ff3d9a;
  --pink: #ff76c1;
  --cyan: #59ecff;
  --violet: #7b3cff;
  --danger: #ff4e5f;
  --glass: rgba(19, 8, 35, 0.58);
  --line: rgba(255, 218, 138, 0.18);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --display: 'Russo One', 'Arial Black', system-ui, sans-serif;
  --body: 'Unbounded', 'Trebuchet MS', system-ui, sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow: hidden;
  overscroll-behavior: none;
  touch-action: none;
}

body {
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button { font: inherit; color: inherit; }
button:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
[hidden] { display: none !important; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(120% 80% at 50% -10%, #2a0a43 0%, transparent 50%),
    radial-gradient(100% 70% at 50% 115%, #19072c 0%, transparent 60%),
    var(--bg);
}

#stage {
  position: absolute;
  inset: 0;
  z-index: 0;
}
#stage canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  outline: none;
}

.atmosphere {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(90% 60% at 50% 38%, transparent 35%, rgba(4, 1, 9, 0.44) 100%),
    linear-gradient(180deg, rgba(4, 1, 9, 0.55) 0%, transparent 16%, transparent 76%, rgba(4, 1, 9, 0.72) 100%);
}

.grain {
  position: absolute;
  inset: -50%;
  z-index: 3;
  pointer-events: none;
  opacity: 0.055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: grain 0.7s steps(2) infinite;
}
@keyframes grain {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(-1%, -1%); }
  100% { transform: translate(2%, 2%); }
}

/* --------------------------------------------------------------------------
   HUD
   -------------------------------------------------------------------------- */
.hud {
  position: absolute;
  inset: 0 0 auto 0;
  z-index: 20;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: start;
  gap: 18px;
  padding:
    calc(18px + var(--safe-top))
    calc(26px + var(--safe-right))
    18px
    calc(26px + var(--safe-left));
  pointer-events: none;
  opacity: 1;
  transform: translateY(0);
  transition: opacity 0.45s ease, transform 0.45s ease;
}
.hud > * { pointer-events: auto; }

body[data-state="menu"] .hud,
body[data-state="boot"] .hud,
body[data-state="over"] .hud {
  opacity: 0;
  transform: translateY(-14px);
  pointer-events: none;
}
body[data-state="pause"] .hud { opacity: 0.22; }

.hud-cluster { display: flex; align-items: flex-start; gap: 14px; min-width: 0; }
.hud-cluster--center {
  flex-direction: column;
  align-items: center;
  gap: 0;
  min-width: 180px;
  text-align: center;
}
.hud-cluster--right { justify-content: flex-end; align-items: center; gap: 18px; }

.brand { display: flex; align-items: center; gap: 9px; }
.brand-star {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  color: var(--gold);
  font-size: 17px;
  filter: drop-shadow(0 0 9px rgba(255, 209, 102, 0.8));
}
.brand-text {
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.12em;
  line-height: 1;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.7);
}
.brand-text em {
  display: block;
  margin-top: 3px;
  font-style: normal;
  font-size: 9px;
  letter-spacing: 0.54em;
  color: var(--gold);
}

.lives { display: flex; gap: 5px; margin-top: 30px; position: absolute; }
.life {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.14);
  transition: color 0.2s, text-shadow 0.2s, transform 0.2s;
}
.life.is-on { color: var(--gold); text-shadow: 0 0 12px rgba(255, 209, 102, 0.8); }
.life.is-lost { color: rgba(255, 78, 95, 0.45); transform: scale(0.75); }

.zone-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 30px;
  padding: 4px 9px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 99px;
  background: rgba(10, 3, 20, 0.4);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--muted);
  backdrop-filter: blur(6px);
}
.zone-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  animation: blink 1.6s ease-in-out infinite;
}

.score-label {
  font-size: 9px;
  letter-spacing: 0.46em;
  color: var(--gold);
  text-indent: 0.46em;
  opacity: 0.85;
  text-shadow: 0 0 10px rgba(255, 209, 102, 0.4);
}
.score {
  font-family: var(--display);
  font-size: clamp(30px, 3.3vw, 46px);
  line-height: 1;
  letter-spacing: 0.06em;
  text-indent: 0.06em;
  color: #fff9ea;
  text-shadow: 0 0 16px rgba(255, 209, 102, 0.4), 0 4px 30px rgba(0, 0, 0, 0.7);
  font-variant-numeric: tabular-nums;
}
.combo {
  margin-top: 4px;
  font-size: 9px;
  letter-spacing: 0.16em;
  color: var(--pink);
  opacity: 0;
  transform: translateY(-4px) scale(0.9);
  transition: opacity 0.2s, transform 0.2s;
}
.combo.is-live { opacity: 1; transform: translateY(0) scale(1); }
.combo b { font-family: var(--display); font-weight: 400; font-size: 12px; }

.stat { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; }
.stat-label { font-size: 8px; letter-spacing: 0.28em; color: var(--muted-2); }
.stat-value {
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.06em;
  line-height: 1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.stat-value span { font-size: 10px; color: var(--muted); margin-left: 2px; }
.stat--coin {
  flex-direction: row;
  align-items: center;
  gap: 7px;
  padding: 7px 12px;
  border: 1px solid rgba(255, 209, 102, 0.25);
  border-radius: 99px;
  background: rgba(31, 15, 8, 0.48);
  box-shadow: inset 0 0 18px rgba(255, 209, 102, 0.08);
}
.stat--coin .stat-value { color: var(--gold-hot); font-size: 15px; }

.mic-icon {
  position: relative;
  display: block;
  width: 9px;
  height: 13px;
  border-radius: 5px;
  background: linear-gradient(180deg, #fff3c4, var(--gold) 55%, #b87413);
  transform: rotate(-24deg);
  box-shadow: 0 0 9px rgba(255, 209, 102, 0.55);
}
.mic-icon::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 12px;
  width: 2px;
  height: 6px;
  margin-left: -1px;
  background: var(--gold);
}

.hud-buttons { display: flex; gap: 8px; }
.icon-btn {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 50%;
  background: rgba(12, 5, 24, 0.55);
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: border-color 0.2s, background 0.2s, transform 0.15s;
}
.icon-btn:hover { border-color: rgba(255, 209, 102, 0.55); background: rgba(60, 27, 10, 0.55); }
.icon-btn:active { transform: scale(0.92); }

.ico { position: relative; display: block; }
.ico--sound::before {
  content: '';
  position: absolute;
  left: -5px;
  top: -4px;
  border: 5px solid transparent;
  border-right: 6px solid var(--ink);
  border-left: 0;
}
.ico--sound::after {
  content: '';
  position: absolute;
  left: 2px;
  top: -6px;
  width: 3px;
  height: 12px;
  border: 1.5px solid var(--ink);
  border-left: 0;
  border-radius: 0 99px 99px 0;
}
.is-muted .ico--sound::after { border-color: transparent; }
.is-muted .ico--sound {
  transform: rotate(-18deg);
}
.is-muted .ico--sound::before { background: var(--danger); }
.ico--pause::before,
.ico--pause::after {
  content: '';
  position: absolute;
  top: -7px;
  width: 3px;
  height: 14px;
  border-radius: 1px;
  background: var(--ink);
}
.ico--pause::before { left: -4px; }
.ico--pause::after { right: -4px; }

/* --------------------------------------------------------------------------
   Zone toast / combo toasts
   -------------------------------------------------------------------------- */
.zone-toast {
  position: absolute;
  z-index: 24;
  top: 19%;
  left: 50%;
  transform: translate(-50%, -12px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 12px 28px 14px;
  pointer-events: none;
  opacity: 0;
  background: linear-gradient(90deg, transparent, rgba(10, 3, 20, 0.55) 20%, rgba(10, 3, 20, 0.55) 80%, transparent);
  border-top: 1px solid rgba(255, 209, 102, 0.28);
  border-bottom: 1px solid rgba(255, 209, 102, 0.28);
  clip-path: polygon(7% 0, 93% 0, 100% 50%, 93% 100%, 7% 100%, 0 50%);
}
.zone-toast.is-show { animation: zoneToast 3.2s ease both; }
.zone-toast__kicker { font-size: 8px; letter-spacing: 0.34em; color: var(--gold); }
.zone-toast__name {
  font-family: var(--display);
  font-size: 28px;
  letter-spacing: 0.14em;
  text-indent: 0.14em;
  color: var(--ink);
  text-shadow: 0 0 22px rgba(255, 61, 154, 0.6);
}
@keyframes zoneToast {
  0% { opacity: 0; transform: translate(-50%, -22px) scale(0.96); }
  12%, 78% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  100% { opacity: 0; transform: translate(-50%, 8px) scale(0.98); }
}

.toasts {
  position: absolute;
  z-index: 26;
  top: 28%;
  right: max(5vw, 26px);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  pointer-events: none;
}
.toast {
  padding: 6px 12px 7px;
  border-right: 2px solid var(--gold);
  background: linear-gradient(270deg, rgba(36, 15, 5, 0.74), transparent);
  font-size: 10px;
  letter-spacing: 0.16em;
  color: var(--gold-hot);
  animation: toastIn 1.4s ease both;
  text-shadow: 0 0 12px rgba(255, 209, 102, 0.45);
}
.toast--encore { color: var(--cyan); border-color: var(--cyan); text-shadow: 0 0 12px rgba(89, 236, 255, 0.5); }
.toast--combo { color: var(--pink); border-color: var(--pink); }
@keyframes toastIn {
  0% { opacity: 0; transform: translateX(18px); }
  12%, 68% { opacity: 1; transform: translateX(0); }
  100% { opacity: 0; transform: translateX(9px); }
}

/* --------------------------------------------------------------------------
   Screens
   -------------------------------------------------------------------------- */
.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  transition: opacity 0.4s ease, visibility 0.4s;
}
.screen[hidden] { display: none; }

.screen--start {
  padding:
    calc(22px + var(--safe-top))
    calc(5vw + var(--safe-right))
    calc(18px + var(--safe-bottom))
    calc(7vw + var(--safe-left));
  justify-content: space-between;
  background:
    radial-gradient(58% 72% at 23% 48%, rgba(8, 2, 17, 0.82) 0%, rgba(8, 2, 17, 0.42) 52%, transparent 78%),
    linear-gradient(90deg, rgba(5, 1, 11, 0.62) 0%, transparent 55%),
    linear-gradient(180deg, rgba(5, 1, 11, 0.7) 0%, transparent 18%, transparent 80%, rgba(5, 1, 11, 0.62) 100%);
}

.start-top { display: flex; }
.marquee-badge {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px 9px 14px;
  border: 1px solid rgba(255, 209, 102, 0.28);
  border-radius: 4px;
  background: rgba(12, 4, 26, 0.52);
  font-size: 8px;
  letter-spacing: 0.23em;
  color: var(--muted);
  backdrop-filter: blur(8px);
  box-shadow: inset 0 0 26px rgba(255, 209, 102, 0.05);
}
.marquee-badge::before,
.marquee-badge::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
}
.marquee-badge::before { left: -2px; top: -2px; }
.marquee-badge::after { right: -2px; bottom: -2px; }
.marquee-lights {
  width: 52px;
  height: 5px;
  background-image: radial-gradient(circle, var(--gold) 1.4px, transparent 1.8px);
  background-size: 9px 5px;
  background-repeat: repeat-x;
  filter: drop-shadow(0 0 4px rgba(255, 209, 102, 0.8));
  animation: marquee 1.1s linear infinite;
}
@keyframes marquee { to { background-position: 9px 0; } }
.marquee-sep { color: var(--gold); opacity: 0.5; }

.start-main {
  width: min(690px, 55vw);
  padding-bottom: 2vh;
}
.kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 12px;
  font-size: 8px;
  letter-spacing: 0.34em;
  color: var(--gold);
  text-shadow: 0 0 12px rgba(255, 209, 102, 0.45);
}
.kicker-line { width: 24px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.kicker-line:last-child { transform: scaleX(-1); }

.hero-title {
  margin: 0;
  font-family: var(--display);
  font-weight: 400;
  line-height: 0.79;
  letter-spacing: -0.012em;
}
.hero-line { display: block; white-space: nowrap; }
.hero-line--1,
.hero-line--2 {
  background: linear-gradient(180deg, #fffdf6 0%, #ffeec3 24%, #ffd166 48%, #fff6d9 60%, #d99a2b 82%, #8d5710 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 4px 0 rgba(55, 23, 3, 0.55)) drop-shadow(0 0 26px rgba(255, 183, 69, 0.22));
}
.hero-line--1 { font-size: clamp(54px, 8.2vw, 122px); }
.hero-line--2 { font-size: clamp(48px, 7.3vw, 110px); letter-spacing: 0.005em; }
.hero-line--3 {
  display: flex;
  align-items: center;
  gap: 0.18em;
  margin-top: 0.22em;
  font-size: clamp(29px, 3.5vw, 54px);
  letter-spacing: 0.28em;
  color: rgba(255, 255, 255, 0.92);
}
.hero-line--3 i {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 1.08em;
  padding: 0 0.16em;
  border: 1px solid rgba(89, 236, 255, 0.65);
  border-radius: 3px;
  background: rgba(31, 9, 57, 0.5);
  font-style: normal;
  font-size: 0.62em;
  letter-spacing: 0.12em;
  color: var(--cyan);
  box-shadow: 0 0 22px rgba(89, 236, 255, 0.22), inset 0 0 18px rgba(89, 236, 255, 0.12);
  text-shadow: 0 0 12px rgba(89, 236, 255, 0.7);
}
.hero-line--3 b { font-weight: 400; }

.hero-sub {
  margin: 16px 0 0;
  font-size: 9px;
  letter-spacing: 0.25em;
  color: rgba(255, 255, 255, 0.56);
}
.hero-copy {
  max-width: 470px;
  margin: 12px 0 0;
  font-size: 11px;
  line-height: 1.65;
  letter-spacing: 0.02em;
  color: var(--muted);
  font-weight: 300;
}

.start-actions {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-top: 25px;
}
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  min-height: 54px;
  padding: 0 30px;
  border: 0;
  border-radius: 3px;
  font-family: var(--display);
  font-size: 14px;
  letter-spacing: 0.17em;
  text-indent: 0.17em;
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.15s ease, filter 0.2s ease, box-shadow 0.2s ease;
}
.btn::after {
  content: '';
  position: absolute;
  inset: 2px;
  border: 1px solid rgba(255, 255, 255, 0.32);
  border-radius: 2px;
  pointer-events: none;
}
.btn--play {
  color: #2a1200;
  background: linear-gradient(135deg, #fff3bf 0%, #ffd166 32%, #ffb733 62%, #ffe79e 100%);
  box-shadow:
    0 0 0 1px rgba(255, 220, 140, 0.6),
    0 8px 30px rgba(255, 157, 26, 0.28),
    0 0 70px rgba(255, 183, 51, 0.16),
    inset 0 -3px 0 rgba(128, 65, 0, 0.35);
}
.btn--play:hover { transform: translateY(-2px); filter: brightness(1.06); box-shadow: 0 0 0 1px rgba(255, 220, 140, 0.8), 0 12px 42px rgba(255, 157, 26, 0.38), 0 0 90px rgba(255, 183, 51, 0.24), inset 0 -3px 0 rgba(128, 65, 0, 0.35); }
.btn--play:active { transform: translateY(1px) scale(0.99); }
.btn-play-icon {
  width: 0;
  height: 0;
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
  border-left: 9px solid #3a1900;
  filter: drop-shadow(0 0 2px rgba(255, 255, 255, 0.4));
}
.btn-shine {
  position: absolute;
  top: -30%;
  bottom: -30%;
  width: 28%;
  left: -40%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.85), transparent);
  transform: skewX(-20deg);
  animation: shine 3.4s ease-in-out infinite;
}
@keyframes shine {
  0%, 62% { left: -40%; }
  86%, 100% { left: 130%; }
}
.btn--gold {
  color: #241000;
  background: linear-gradient(135deg, #ffe9a8, #ffbe45);
  box-shadow: 0 6px 26px rgba(255, 157, 26, 0.25);
}
.btn--ghost {
  color: var(--ink);
  background: rgba(19, 8, 35, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(8px);
}
.btn--ghost::after { display: none; }
.btn--ghost:hover { border-color: rgba(255, 209, 102, 0.6); color: var(--gold-hot); }

.best-pill {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-left: 18px;
  border-left: 1px solid rgba(255, 209, 102, 0.25);
}
.best-pill span { font-size: 7px; letter-spacing: 0.3em; color: var(--muted-2); }
.best-pill b {
  font-family: var(--display);
  font-size: 20px;
  font-weight: 400;
  letter-spacing: 0.08em;
  color: var(--gold-hot);
  text-shadow: 0 0 16px rgba(255, 209, 102, 0.35);
  font-variant-numeric: tabular-nums;
}

.controls-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  max-width: 600px;
  margin-top: 25px;
  padding-top: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}
.control-item { display: flex; align-items: center; gap: 9px; min-width: 0; }
.control-item > span:last-child { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.control-item b { font-size: 8.5px; letter-spacing: 0.12em; color: rgba(255, 255, 255, 0.85); font-weight: 500; }
.control-item small { font-size: 6.4px; line-height: 1.35; letter-spacing: 0.03em; color: var(--muted-2); font-weight: 300; }
.keys { display: flex; gap: 3px; flex: none; }
kbd {
  display: grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  padding: 0 5px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom-width: 2px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.055);
  font-family: var(--body);
  font-size: 8.5px;
  font-weight: 500;
  color: var(--ink);
}
kbd.kbd-wide { font-size: 6.2px; letter-spacing: 0.06em; }

.start-foot {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 7px;
  letter-spacing: 0.2em;
  color: rgba(255, 255, 255, 0.34);
}
.foot-star { color: var(--gold); opacity: 0.7; font-size: 8px; }

/* Pause + game over */
.screen--pause,
.screen--over {
  align-items: center;
  justify-content: center;
  padding: calc(20px + var(--safe-top)) 20px calc(20px + var(--safe-bottom));
  background:
    radial-gradient(60% 60% at 50% 45%, rgba(19, 7, 37, 0.55), transparent 75%),
    rgba(4, 1, 9, 0.72);
  backdrop-filter: blur(9px);
}
.modal {
  position: relative;
  width: min(480px, 92vw);
  padding: 38px 42px 32px;
  border: 1px solid rgba(255, 209, 102, 0.3);
  background:
    linear-gradient(165deg, rgba(31, 12, 48, 0.92), rgba(9, 3, 19, 0.96)),
    radial-gradient(circle at 50% 0%, rgba(255, 209, 102, 0.15), transparent 60%);
  box-shadow: var(--shadow), 0 0 80px rgba(255, 61, 154, 0.08), inset 0 0 70px rgba(255, 209, 102, 0.03);
  text-align: center;
  animation: modalIn 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.modal::before,
.modal::after {
  content: '';
  position: absolute;
  width: 16px;
  height: 16px;
  border-color: var(--gold);
  border-style: solid;
  opacity: 0.7;
}
.modal::before { top: 7px; left: 7px; border-width: 1px 0 0 1px; }
.modal::after { bottom: 7px; right: 7px; border-width: 0 1px 1px 0; }
@keyframes modalIn {
  from { opacity: 0; transform: translateY(18px) scale(0.97); }
  to { opacity: 1; transform: none; }
}
.modal-kicker {
  margin: 0 0 10px;
  font-size: 8px;
  letter-spacing: 0.34em;
  color: var(--gold);
}
.modal-title {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(38px, 6vw, 58px);
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.08em;
  background: linear-gradient(180deg, #fff, #ffd166 55%, #b57416);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 24px rgba(255, 183, 69, 0.22));
}
.modal-copy { margin: 14px 0 24px; font-size: 10px; letter-spacing: 0.08em; color: var(--muted); font-weight: 300; }
.modal-actions { display: flex; gap: 10px; justify-content: center; margin-top: 24px; flex-wrap: wrap; }
.text-btn {
  margin-top: 18px;
  padding: 4px 8px;
  border: 0;
  background: none;
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--muted-2);
  cursor: pointer;
}
.text-btn:hover { color: var(--gold); }

.modal--result { width: min(520px, 93vw); padding: 32px 38px 28px; }
.new-best {
  display: inline-block;
  margin: 10px 0 0;
  padding: 5px 13px;
  border: 1px solid rgba(255, 209, 102, 0.55);
  border-radius: 99px;
  font-size: 8px;
  letter-spacing: 0.26em;
  color: var(--gold-hot);
  background: rgba(255, 183, 51, 0.1);
  box-shadow: 0 0 24px rgba(255, 183, 51, 0.18);
  animation: newBest 1.6s ease-in-out infinite;
}
@keyframes newBest {
  50% { box-shadow: 0 0 38px rgba(255, 183, 51, 0.4); filter: brightness(1.12); }
}
.result-score { margin: 20px 0 6px; }
.result-score span { display: block; font-size: 8px; letter-spacing: 0.32em; color: var(--muted-2); }
.result-score b {
  display: block;
  margin-top: 3px;
  font-family: var(--display);
  font-size: clamp(48px, 9vw, 72px);
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.04em;
  color: #fff8e8;
  text-shadow: 0 0 30px rgba(255, 209, 102, 0.35);
  font-variant-numeric: tabular-nums;
}
.result-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.result-grid > div { padding: 13px 6px; }
.result-grid > div + div { border-left: 1px solid rgba(255, 255, 255, 0.1); }
.result-grid span { display: block; font-size: 7px; letter-spacing: 0.2em; color: var(--muted-2); }
.result-grid b {
  display: block;
  margin-top: 5px;
  font-family: var(--display);
  font-size: 17px;
  font-weight: 400;
  letter-spacing: 0.05em;
  color: var(--ink);
}
.modal-quote { margin: 22px 0 0; font-size: 8px; font-style: italic; letter-spacing: 0.08em; color: var(--muted-2); }

/* --------------------------------------------------------------------------
   Encore meter
   -------------------------------------------------------------------------- */
.encore {
  position: absolute;
  z-index: 22;
  left: 50%;
  bottom: calc(24px + var(--safe-bottom));
  width: min(330px, 46vw);
  transform: translateX(-50%);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease, transform 0.4s ease;
}
body[data-state="playing"] .encore,
body[data-state="pause"] .encore {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
body[data-state="menu"] .encore { transform: translateX(-50%) translateY(12px); }
.encore-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 5px;
}
.encore-label {
  font-size: 8px;
  letter-spacing: 0.3em;
  color: var(--gold);
  text-shadow: 0 0 12px rgba(255, 209, 102, 0.4);
}
.encore-star { color: var(--gold); margin-right: 3px; }
.encore-btn {
  padding: 3px 9px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 99px;
  background: rgba(10, 3, 20, 0.5);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: var(--muted-2);
  cursor: pointer;
  transition: all 0.25s;
  pointer-events: auto;
}
.encore-btn:disabled { cursor: default; }
.encore.is-ready .encore-btn {
  border-color: var(--cyan);
  color: #06222a;
  background: var(--cyan);
  box-shadow: 0 0 20px rgba(89, 236, 255, 0.55);
  animation: readyPulse 1.1s ease-in-out infinite;
}
@keyframes readyPulse {
  50% { box-shadow: 0 0 34px rgba(89, 236, 255, 0.85); filter: brightness(1.15); }
}
.encore-track {
  position: relative;
  height: 7px;
  overflow: hidden;
  border: 1px solid rgba(255, 209, 102, 0.22);
  border-radius: 99px;
  background: rgba(9, 3, 18, 0.7);
  box-shadow: inset 0 1px 4px rgba(0, 0, 0, 0.6);
}
.encore-fill {
  position: absolute;
  inset: 1px auto 1px 1px;
  width: 0%;
  border-radius: 99px;
  background: linear-gradient(90deg, #a646ff, #ff3d9a 45%, #ffd166 100%);
  box-shadow: 0 0 12px rgba(255, 61, 154, 0.7);
  transition: width 0.2s linear;
}
.encore.is-ready .encore-fill {
  background: linear-gradient(90deg, #ffd166, #59ecff 60%, #ffffff);
  box-shadow: 0 0 18px rgba(89, 236, 255, 0.8);
  animation: encoreFill 0.8s ease-in-out infinite alternate;
}
@keyframes encoreFill { to { filter: brightness(1.35); } }
.encore.is-active .encore-fill { background: linear-gradient(90deg, #59ecff, #ffffff, #59ecff); }
.encore-shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.5), transparent);
  transform: translateX(-120%);
  animation: encoreShine 2.4s ease-in-out infinite;
  mix-blend-mode: overlay;
}
@keyframes encoreShine { 60%, 100% { transform: translateX(120%); } }

/* --------------------------------------------------------------------------
   Touch controls
   -------------------------------------------------------------------------- */
.touch-controls {
  position: absolute;
  z-index: 23;
  left: calc(14px + var(--safe-left));
  right: calc(14px + var(--safe-right));
  bottom: calc(14px + var(--safe-bottom));
  display: none;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  opacity: 0;
  transition: opacity 0.35s;
}
body[data-state="playing"] .touch-controls { opacity: 1; }
.touch-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  width: 68px;
  height: 62px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 14px;
  color: rgba(255, 255, 255, 0.88);
  background: linear-gradient(180deg, rgba(35, 16, 56, 0.62), rgba(9, 3, 18, 0.72));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 8px 24px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(8px);
  touch-action: none;
  cursor: pointer;
}
.touch-btn span { font-size: 18px; line-height: 1; text-shadow: 0 0 10px rgba(255, 255, 255, 0.35); }
.touch-btn small { font-size: 5.6px; letter-spacing: 0.14em; color: var(--muted); }
.touch-btn:active { transform: scale(0.94); border-color: var(--gold); background: rgba(80, 35, 12, 0.6); }
.touch-btn--left,
.touch-btn--right { width: 74px; height: 68px; }
.touch-btn--jump { border-color: rgba(255, 209, 102, 0.32); }
.touch-btn--slide { border-color: rgba(89, 236, 255, 0.28); }
.touch-stack { display: flex; gap: 9px; }
.touch-btn--jump, .touch-btn--slide { width: 64px; height: 52px; }
body[data-state="menu"] .touch-controls,
body[data-state="over"] .touch-controls,
body[data-state="pause"] .touch-controls,
body[data-state="boot"] .touch-controls { opacity: 0; pointer-events: none; }

@media (hover: none), (pointer: coarse), (max-width: 820px) {
  .touch-controls { display: flex; }
}

/* --------------------------------------------------------------------------
   Effects
   -------------------------------------------------------------------------- */
.flash {
  position: absolute;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(circle at 50% 55%, rgba(255, 78, 95, 0.55), transparent 65%);
  mix-blend-mode: screen;
}
.flash.is-hit { animation: flashHit 0.42s ease-out; }
@keyframes flashHit { 0% { opacity: 1; } 100% { opacity: 0; } }
.flash.is-gold { background: radial-gradient(circle at 50% 55%, rgba(255, 209, 102, 0.75), transparent 70%); animation: flashGold 0.7s ease-out; }
@keyframes flashGold { 0% { opacity: 1; } 100% { opacity: 0; } }

.speedlines {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0;
  background: repeating-conic-gradient(from 0deg at 50% 58%, rgba(89, 236, 255, 0.22) 0deg 0.35deg, transparent 0.35deg 5deg);
  mask-image: radial-gradient(55% 55% at 50% 58%, transparent 35%, #000 78%);
  -webkit-mask-image: radial-gradient(55% 55% at 50% 58%, transparent 35%, #000 78%);
  transition: opacity 0.3s;
  animation: speedSpin 5s linear infinite;
}
.speedlines.is-on { opacity: 0.5; }
@keyframes speedSpin { to { transform: rotate(3deg) scale(1.04); } }

/* --------------------------------------------------------------------------
   Boot
   -------------------------------------------------------------------------- */
.boot {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  background:
    radial-gradient(55% 55% at 50% 50%, #1a072c, #06030c 75%);
  transition: opacity 0.7s ease, visibility 0.7s;
}
