};

const state = {
  mode: 'boot',
  distance: 0,
  speed: 17,
  score: 0,
  coins: 0,
  lives: 3,
  combo: 1,
  streak: 0,
  comboTimer: 0,
  encoreFill: 0,
  encoreActive: false,
  encoreTimer: 0,
  encoreDuration: 6.5,
  encoreReady: false,
  invuln: 0,
  hitStop: 0,
  shake: 0,
  lane: 1,
  x: 0,
  y: 0,
  vy: 0,
  sliding: 0,
  fastFall: false,
  zoneIdx: -1,
  best: 0,
  newBest: false,
  runTime: 0,
  menuScroll: 0,
  started: false,
};

try {
  state.best = Number(localStorage.getItem('kirkorov-run-best') || 0) || 0;
} catch { state.best = 0; }

let renderer;
try {
  renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance', alpha: false });
} catch (error) {
  console.error(error);
  els.bootError.hidden = false;
