const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const results = [];
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
    const failures = [];
    page.on('pageerror', (e) => { console.log(`[${name}] PAGEERROR`, e.message); failures.push(e.message); });
    page.on('console', (msg) => { if (msg.type() === 'error') console.log(`[${name}] CONSOLE`, msg.text()); });
    page.on('response', (r) => { if (r.status() >= 400) console.log(`[${name}] HTTP`, r.status(), r.url()); });
    await page.goto('http://localhost:3002', { waitUntil: 'networkidle', timeout: 45000 });
    await page.waitForTimeout(2200);
    const info = await page.evaluate(() => ({
      state: document.body.dataset.state,
      canvas: !!document.querySelector('canvas'),
      size: [innerWidth, innerHeight],
      renderer: (() => { const c = document.querySelector('canvas'); const gl = c?.getContext('webgl2') || c?.getContext('webgl'); return gl ? gl.getParameter(gl.VERSION) : null; })(),
      errors: window.__kirkorov ? null : 'game not ready',
      world: window.__kirkorov ? {
        obstacles: window.__kirkorov.world.obstacles.length,
        coins: window.__kirkorov.world.coins.length,
        mode: window.__kirkorov.state.mode,
      } : null,
    }));
    console.log(name, JSON.stringify(info));
    await page.screenshot({ path: join(out, `menu-${name}.png`) });
    const start = await page.locator('#play-btn');
    await start.click({ timeout: 5000 }).catch((e) => console.log('click failed', e.message));
    await page.waitForTimeout(1200);
    const gameInfo = await page.evaluate(() => ({
      state: document.body.dataset.state,
      score: document.getElementById('score').textContent,
      obstacles: window.__kirkorov?.world.obstacles.length,
      coins: window.__kirkorov?.world.coins.length,
      distance: window.__kirkorov?.state.distance,
      lives: window.__kirkorov?.state.lives,
      x: window.__kirkorov?.state.x,
    }));
    console.log(name, 'game', JSON.stringify(gameInfo));
    await page.screenshot({ path: join(out, `game-${name}.png`) });
    await page.waitForTimeout(2500);
    const later = await page.evaluate(() => ({
      state: document.body.dataset.state,
      score: window.__kirkorov?.state.score,
      distance: window.__kirkorov?.state.distance,
      lives: window.__kirkorov?.state.lives,
      mode: window.__kirkorov?.state.mode,
      fps: null,
    }));
    console.log(name, 'later', JSON.stringify(later));
    await page.screenshot({ path: join(out, `later-${name}.png`) });
    results.push({ name, failures });
    await page.close();
  }
  console.log('done', JSON.stringify(results));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

