const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = createRequire(join(runtime, 'package.json'))('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const measure = `async () => {
  const start = performance.now(); let frames = 0;
  await new Promise((resolve) => { function tick(){ frames++; if (performance.now()-start>1500) resolve(); else requestAnimationFrame(tick);} requestAnimationFrame(tick); });
  return Math.round(frames / ((performance.now()-start)/1000) * 10) / 10;
}`;

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
  const t0 = Date.now();
  await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
  console.log('loaded', Date.now()-t0);
  await page.waitForTimeout(25000);
  console.log('baseline fps', await page.evaluate(eval(measure)));

  const steps = [
    ['hide beams', 'window.__kirkorov.world.beams.forEach(b => b.mesh.visible = false)'],
    ['hide ambient+particles', 'window.__kirkorov.world.ambient.visible=false;window.__kirkorov.world.particles.points.visible=false;window.__kirkorov.world.crowdLights.visible=false'],
    ['hide arches', 'window.__kirkorov.world.arches.forEach(a => a.visible=false)'],
    ['hide sky+city+ball', 'window.__kirkorov.world.sky.visible=false;window.__kirkorov.world.city.visible=false;window.__kirkorov.world.city2.visible=false;window.__kirkorov.world.ballGroup.visible=false'],
    ['hide character', 'window.__kirkorov.runner.group.visible=false'],
    ['hide floor', 'window.__kirkorov.world.floor.visible=false'],
    ['hide crowd', 'window.__kirkorov.world.scene.children.filter(o=>o.isInstancedMesh).forEach(o=>o.visible=false)'],
    ['hide coins+obstacles', 'window.__kirkorov.world.obstacles.forEach(o=>o.mesh.visible=false);window.__kirkorov.world.coins.forEach(c=>c.mesh.visible=false)'],
  ];
  for (const [label, code] of steps) {
    await page.evaluate(code);
    await page.waitForTimeout(300);
    const fps = await page.evaluate(eval(measure));
    console.log(label, fps);
  }
  // pixel ratio test
  await page.evaluate('window.__kirkorov.renderer.setPixelRatio(0.6)');
  console.log('pixel ratio .6', await page.evaluate(eval(measure)));
  await browser.close();
})();

