const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const meas = `async () => { const start=performance.now(); let frames=0; await new Promise(r=>{function tick(){frames++; if(performance.now()-start>2000) r(); else requestAnimationFrame(tick);}requestAnimationFrame(tick);}); return Math.round(frames/((performance.now()-start)/1000)*10)/10; }`;
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
  const t0 = Date.now();
  await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
  console.log('loaded', Date.now()-t0);
  await page.waitForTimeout(20000);
  console.log('render info', await page.evaluate(() => ({ calls: window.__kirkorov.renderer.info.render.calls, tris: window.__kirkorov.renderer.info.render.triangles, programs: window.__kirkorov.renderer.info.programs.length })));
  await page.evaluate('window.__kirkorov.world.beams.forEach(b=>b.mesh.visible=false)');
  console.log('beams hidden', await page.evaluate(meas));
  for (const pr of [0.85, 0.7, 0.6, 0.5]) {
    await page.evaluate((v)=>window.__kirkorov.renderer.setPixelRatio(v), pr);
    await page.waitForTimeout(500);
    console.log('pr', pr, await page.evaluate(meas));
  }
  await page.evaluate('window.__kirkorov.renderer.setPixelRatio(1)');
  await page.evaluate('window.__kirkorov.renderer.toneMapping = 0');
  await page.waitForTimeout(5000);
  console.log('no tonemap', await page.evaluate(meas));
  await page.evaluate('window.__kirkorov.world.scene.environment = null');
  await page.waitForTimeout(5000);
  console.log('no env', await page.evaluate(meas));
  await page.evaluate('window.__kirkorov.world.rimPink.intensity=0;window.__kirkorov.world.rimCyan.intensity=0;window.__kirkorov.world.warmLight.intensity=0');
  await page.waitForTimeout(5000);
  console.log('no point lights', await page.evaluate(meas));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

