// ---- cape -------------------------------------------------------------
const capeGeo = new THREE.PlaneGeometry(1.46, 1.82, 14, 20);
const capePos = capeGeo.attributes.position;
this.capeBaseZ = new Float32Array(capePos.count);
for (let i = 0; i < capePos.count; i++) {
  const x = capePos.getX(i);
  const y = capePos.getY(i);
  const nx = x / 0.73;
  const t = clamp01((0.91 - y) / 1.82);
  // Flare the hem and carve a soft tail-coat notch into the centre.
  const width = 0.9 + 0.36 * t;
  const notch = t > 0.7 ? ((t - 0.7) / 0.3) ** 2 * (0.04 + 0.2 * Math.max(0, 1 - Math.abs(nx) * 2.2)) : 0;
  capePos.setX(i, x * width);
  capePos.setY(i, y + notch);
  const billow = Math.sin(t * Math.PI) * 0.13 * (1 - nx * nx * 0.55);
  this.capeBaseZ[i] = billow;
  capePos.setZ(i, billow);
}
capeGeo.computeVertexNormals();
this.capeBase = capeGeo.attributes.position.array.slice();
const capeMat = new THREE.MeshBasicMaterial({
  map: capeTexture(),
  color: 0xffffff,
  side: THREE.DoubleSide,
  toneMapped: false,
});
this.materials.push(capeMat);
this.capeMat = capeMat;
this.cape = new THREE.Mesh(capeGeo, capeMat);
this.cape.position.set(0, 1.02, 0.26);
this.cape.rotation.x = -0.07;
this.pose.add(this.cape);

