const capeGeo = new THREE.PlaneGeometry(1.46, 1.82, 16, 22);
const capePos = capeGeo.attributes.position;
this.capeBaseZ = new Float32Array(capePos.count);
for (let i = 0; i < capePos.count; i++) {
  const x = capePos.getX(i);
  const y = capePos.getY(i);
  const nx = x / 0.73;
  const t = clamp01((0.91 - y) / 1.82);
  // Narrow at the shoulders, flared at the hem, with a deep tail-coat split.
  const width = 0.66 + 0.5 * t;
  let notch = 0;
  if (t > 0.45) {
    const k = (t - 0.45) / 0.55;
    notch = k * k * 0.76 * Math.max(0, 1 - Math.abs(nx) * 2.1);
  }
  capePos.setX(i, x * width);
  capePos.setY(i, y + notch);
  const billow = Math.sin(t * Math.PI) * 0.13 * (1 - nx * nx * 0.55);
  this.capeBaseZ[i] = billow;
  capePos.setZ(i, billow);
}

