const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = createRequire(join(runtime, 'package.json'))('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } });
    const errors = [];
    page.on('pageerror', (e) => { console.log(`[${name}] ERROR`, e.message); errors.push(e.message); });
    page.on('console', (m) => { if (m.type() === 'error') console.log(`[${name}] console`, m.text()); });
    const t0 = Date.now();
    await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 90000 });
    console.log(name, 'loaded ms', Date.now() - t0);
    await page.waitForTimeout(12000);
    const menuInfo = await page.evaluate(() => ({ state: document.body.dataset.state, calls: window.__kirkorov?.renderer.info.render.calls, tris: window.__kirkorov?.renderer.info.render.triangles, progs: window.__kirkorov?.renderer.info.programs.length }));
    console.log(name, 'menu', menuInfo);
    await page.screenshot({ path: join(out, `menu-${name}.png`) });
    await page.locator('#play-btn').click({ timeout: 20000 });
    await page.waitForTimeout(1500);
    const gameInfo = await page.evaluate(() => ({ state: document.body.dataset.state, calls: window.__kirkorov.renderer.info.render.calls, score: document.getElementById('score').textContent, lives: window.__kirkorov.state.lives, distance: window.__kirkorov.state.distance, obstacles: window.__kirkorov.world.obstacles.length, coins: window.__kirkorov.world.coins.length }));
    console.log(name, 'game', gameInfo);
    await page.screenshot({ path: join(out, `game-${name}.png`) });
    await page.waitForTimeout(4000);
    const later = await page.evaluate(() => ({ state: document.body.dataset.state, score: window.__kirkorov.state.score, lives: window.__kirkorov.state.lives, distance: window.__kirkorov.state.distance, mode: window.__kirkorov.state.mode }));
    console.log(name, 'later', later);
    await page.screenshot({ path: join(out, `later-${name}.png`) });
    console.log(name, 'errors', errors);
    await page.close();
  }
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

