457:         hipTarget = Math.sin(sidePhase) * legAmp;
458:         kneeTarget = -Math.max(0, Math.sin(sidePhase + Math.PI * 0.55)) * 1.15;
459:       } else if (jumping) {
460:         hipTarget = i === 0 ? -0.75 : -0.25;
461:         kneeTarget = i === 0 ? 1.2 : 0.55;
462:       } else if (idle) {
463:         hipTarget = 0.02;
464:         kneeTarget = 0.02;
465:       } else if (slide) {
466:         hipTarget = -1.28;
467:         kneeTarget = 0.18;
468:       }
