470:       leg.knee.rotation.x = THREE.MathUtils.damp(leg.knee.rotation.x, kneeTarget, running ? 18 : 12, dt);
471:       leg.hip.rotation.z = THREE.MathUtils.damp(leg.hip.rotation.z, slide ? leg.side * 0.08 : leg.side * 0.02, 10, dt);
