479:       let shoulderZ = arm.side * 0.14;
480:       let elbowX = -0.2;
481:       if (running) {
482:         shoulderX = Math.sin(sidePhase) * 0.72;
483:         elbowX = -0.5 - Math.max(0, Math.sin(sidePhase)) * 0.5;
484:         shoulderZ = arm.side * 0.13;
485:       } else if (jumping) {
486:         shoulderX = -0.9;
487:         shoulderZ = arm.side * 0.42;
488:         elbowX = -0.5;
489:       } else if (idle) {
490:         if (arm.side === -1) {
491:           shoulderX = -0.38 + sway * 0.05;
492:           shoulderZ = 0.72;
493:           elbowX = -1.38;
494:         } else {
495:           shoulderX = -0.15;
496:           shoulderZ = -0.62;
497:           elbowX = -1.15;
498:         }
499:       } else if (slide) {
500:         shoulderX = 0.2;
501:         shoulderZ = arm.side * 0.9;
502:         elbowX = -0.35;
503:       }
504:       arm.shoulder.rotation.x = THREE.MathUtils.damp(arm.shoulder.rotation.x, shoulderX, running ? 18 : 10, dt);
505:       arm.shoulder.rotation.z = THREE.MathUtils.damp(arm.shoulder.rotation.z, shoulderZ, running ? 16 : 10, dt);
506:       arm.elbow.rotation.x = THREE.MathUtils.damp(arm.elbow.rotation.x, elbowX, 14, dt);
507:     }
