const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = createRequire(join(runtime, 'package.json'))('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => { console.log('ERROR', e.message); errors.push(e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 90000 });
  await page.waitForFunction(() => document.getElementById('boot')?.classList.contains('is-done'), null, { timeout: 120000 });
  await page.waitForTimeout(800);
  await page.locator('#play-btn').click({ timeout: 60000 });
  for (const wait of [700, 1500, 3000, 5000]) {
    await page.waitForTimeout(wait);
    const info = await page.evaluate(() => {
      const flash = document.getElementById('flash');
      const boot = document.getElementById('boot');
      const canvas = document.querySelector('canvas');
      const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
      return {
        distance: window.__kirkorov.state.distance,
        mode: window.__kirkorov.state.mode,
        lives: window.__kirkorov.state.lives,
        flashClass: flash.className,
        flashOpacity: getComputedStyle(flash).opacity,
        flashBg: getComputedStyle(flash).backgroundImage.slice(0, 60),
        bootClass: boot.className,
        bootOpacity: getComputedStyle(boot).opacity,
        canvasSize: [canvas.width, canvas.height],
        drawing: gl ? !gl.isContextLost() : 'no-gl',
        bodyState: document.body.dataset.state,
      };
    });
    console.log(wait, JSON.stringify(info));
    await page.screenshot({ path: `/tmp/opencode/shots/t-${wait}.png`, timeout: 120000 });
  }
  console.log('errors', errors);
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

