    const k = window.__kirkorov;
    const lights = [];
    k.world.scene.traverse((o) => { if (o.isLight) lights.push({ type: o.type, intensity: o.intensity, visible: o.visible }); });
    const cape = k.runner.cape;
    return {
      state: document.body.dataset.state,
      mode: k.state.mode,
      distance: k.state.distance,
      capeVisible: cape.visible,
      capeParentVisible: cape.parent.visible,
      capeMatVisible: cape.material.visible,
      capeMap: !!cape.material.map,
      capeMapImage: cape.material.map?.image?.width || null,
      capePosCount: cape.geometry.attributes.position.count,
      calls: k.renderer.info.render.calls,
      programs: k.renderer.info.programs.map((p) => ({ name: p.name, diagnostics: p.diagnostics || null })),
      ctxLost: k.renderer.getContext().isContextLost(),
      lights,
      camera: k.camera.position.toArray(),
    };
  });
  console.log('menu', JSON.stringify(await sceneInfo(), null, 2));
  await page.screenshot({ path: '/tmp/opencode/shots/diag-menu.png', timeout: 120000 });
  await page.locator('#play-btn').click({ timeout: 60000 });
  await page.waitForTimeout(2500);
  console.log('game', JSON.stringify(await sceneInfo(), null, 2));
  await page.screenshot({ path: '/tmp/opencode/shots/diag-game.png', timeout: 120000 });
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

