const { createRequire } = require('node:module');
const { readFileSync, rmSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = createRequire(join(runtime, 'package.json'))('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  for (const mode of process.argv.slice(2)) {
    const dir = `/tmp/opencode/prof-${mode}-${Date.now()}`;
    const ctx = await chromium.launchPersistentContext(dir, { ...config.browser.launchOptions, timeout: 30000 });
    const page = ctx.pages()[0] || await ctx.newPage();
    page.on('console', (m) => { if (m.type() === 'log') console.log('RESULT', m.text()); });
    page.on('pageerror', (e) => console.log('ERROR', e.message));
    const t0 = Date.now();
    await page.goto(`http://localhost:3002/bench.html?mode=${mode}`, { waitUntil: 'commit', timeout: 90000 });
    await page.waitForFunction(() => document.body.dataset.ready === '1', null, { timeout: 180000, polling: 500 });
    console.log('TOTAL', mode, Date.now() - t0);
    await ctx.close();
    rmSync(dir, { recursive: true, force: true });
  }
})().catch((e) => { console.error(e); process.exit(1); });

const { createRequire } = require('node:module');
const { readFileSync, rmSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = createRequire(join(runtime, 'package.json'))('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const dir = `/tmp/opencode/prof-app-${Date.now()}`;
  const ctx = await chromium.launchPersistentContext(dir, { ...config.browser.launchOptions, timeout: 30000 });
  const page = ctx.pages()[0] || await ctx.newPage();
  page.setDefaultTimeout(180000);
  page.on('console', (m) => console.log('CONSOLE', m.type(), m.text().slice(0, 400)));
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
  const t0 = Date.now();
  await page.goto('http://localhost:3002', { waitUntil: 'commit', timeout: 90000 });
  console.log('commit', Date.now() - t0);
  await page.locator('body').waitFor({ state: 'visible', timeout: 180000 });
  console.log('body visible', Date.now() - t0);
  await page.waitForFunction(() => document.getElementById('boot')?.classList.contains('is-done'), null, { timeout: 180000, polling: 250 });
  console.log('boot done', Date.now() - t0);
  console.log(await page.evaluate(() => ({ state: document.body.dataset.state, ready: !!window.__kirkorov, calls: window.__kirkorov?.renderer.info.render.calls })));
  await page.screenshot({ path: '/tmp/opencode/shots/diag3-menu.png', timeout: 120000 });
  await ctx.close();
  rmSync(dir, { recursive: true, force: true });
})().catch((e) => { console.error(e); process.exit(1); });

