const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = createRequire(join(runtime, 'package.json'))('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } });
    const errors = [];
    page.on('pageerror', (e) => { console.log(name, 'ERROR', e.message); errors.push(e.message); });
    await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 90000 });
    await page.waitForFunction(() => document.getElementById('boot')?.classList.contains('is-done'), null, { timeout: 60000 });
    await page.locator('#play-btn').click({ timeout: 10000 });
    await page.waitForTimeout(1500);

    console.log(name, 'start', await page.evaluate(() => ({ mode: window.__kirkorov.state.mode, lives: window.__kirkorov.state.lives, lane: window.__kirkorov.state.lane, y: window.__kirkorov.state.y })));

    await page.keyboard.press('Space');
    await page.waitForTimeout(180);
    console.log(name, 'jump-y', await page.evaluate(() => +window.__kirkorov.state.y.toFixed(2)));
    await page.waitForTimeout(1200);

    await page.keyboard.press('ArrowLeft');
    await page.waitForTimeout(300);
    console.log(name, 'left-lane', await page.evaluate(() => window.__kirkorov.state.lane));
    await page.keyboard.press('ArrowRight');
    await page.waitForTimeout(300);
    console.log(name, 'right-lane', await page.evaluate(() => window.__kirkorov.state.lane));
    await page.keyboard.press('ArrowDown');
    await page.waitForTimeout(140);
    console.log(name, 'slide', await page.evaluate(() => +window.__kirkorov.state.sliding.toFixed(2)));
    await page.waitForTimeout(900);

    await page.locator('#pause-btn').click();
    await page.waitForTimeout(500);
    console.log(name, 'paused', await page.evaluate(() => ({ mode: window.__kirkorov.state.mode, pauseHidden: document.getElementById('pause-screen').hidden })));
    await page.screenshot({ path: join(out, `pause-${name}.png`), timeout: 120000 });
    await page.locator('#resume-btn').click();
    await page.waitForTimeout(400);
    console.log(name, 'resumed', await page.evaluate(() => window.__kirkorov.state.mode));

    await page.evaluate(() => { window.__kirkorov.state.encoreFill = 100; window.__kirkorov.activateEncore(); });
    await page.waitForTimeout(500);
    console.log(name, 'encore', await page.evaluate(() => ({ active: window.__kirkorov.state.encoreActive, fill: window.__kirkorov.state.encoreFill, cape: window.__kirkorov.runner.capeMat.color.getHexString() })));
    await page.screenshot({ path: join(out, `encore-${name}.png`), timeout: 120000 });
    await page.waitForTimeout(6500);

    await page.evaluate(() => {
      const k = window.__kirkorov;
      k.state.lives = 0;
      k.state.invuln = 0;
      const o = k.world.obstacles.find((x) => x.active && !x.hit);
      if (o) {
        k.state.lane = o.x < -1 ? 0 : o.x > 1 ? 2 : 1;
        k.state.x = o.x;
      }
    });
    await page.waitForFunction(() => window.__kirkorov.state.mode === 'over', null, { timeout: 30000 });
    await page.waitForTimeout(400);
    console.log(name, 'over', await page.evaluate(() => ({ mode: window.__kirkorov.state.mode, screenHidden: document.getElementById('over-screen').hidden, final: document.getElementById('final-score').textContent })));
    await page.screenshot({ path: join(out, `over-${name}.png`), timeout: 120000 });
    console.log(name, 'errors', errors);
    await page.close();
  }
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

